    /// <summary>一个图标 = 一个 DrawingImage(Geometry 与 Brush 全部 Freeze, 可跨实例共享)。</summary>
    private static ImageSource Icon(params (string Path, string Color)[] raw)
    {
        var group = new DrawingGroup();

        // ★ 先垫一个"透明的 24x24" : 官方图标都不是满幅的(实测图形只占 x/y 各约 2~22),
        //   不加这个框, DrawingImage 的 Bounds 就是图形自身的大小 —— 30 个分区各有各的尺寸,
        //   界面上一排看过去大的大、小的小。垫满 24x24 后所有图标同尺度。
        var box = new RectangleGeometry(new Rect(0, 0, 24, 24));
        box.Freeze();
        var transparent = new SolidColorBrush(Color.FromArgb(0, 0, 0, 0));
        transparent.Freeze();
        var backdrop = new GeometryDrawing(transparent, null, box);
        backdrop.Freeze();
        group.Children.Add(backdrop);

        foreach (var (path, color) in raw)
        {
            var geo = Geometry.Parse(path);
            geo.Freeze();
            var brush = new SolidColorBrush((Color)ColorConverter.ConvertFromString(color)!);
            brush.Freeze();

            // 官方图里绝大多数 path 是**闭合填充图形**(以 z 收尾), 但个别是**不闭合的描边线**
            // (实测只有 三农 的最后一笔: "M11.74896 19.16765C10.6297…", 没有 z)。
            // 对这种只能描边, 用填充画会得到一块封口后的怪形状。
            var closed = path.TrimEnd().EndsWith("z", StringComparison.OrdinalIgnoreCase);
            GeometryDrawing drawing;
            if (closed)
            {
                drawing = new GeometryDrawing(brush, null, geo);
            }
            else
            {
                var pen = new Pen(brush, 1.6) { StartLineCap = PenLineCap.Round, EndLineCap = PenLineCap.Round };
                pen.Freeze();
                drawing = new GeometryDrawing(null, pen, geo);
            }
            drawing.Freeze();
            group.Children.Add(drawing);
        }

        group.Freeze();
        var image = new DrawingImage(group);
        image.Freeze();
        return image;
    }

