        // 切成 3 列(每列 10 个)。
        const int columnCount = 3;
        var columns = new List<IReadOnlyList<PartitionItem>>(columnCount);
        var perColumn = (all.Count + columnCount - 1) / columnCount;
        for (var i = 0; i < columnCount; i++)
        {
            var slice = new List<PartitionItem>(perColumn);
            for (var j = i * perColumn; j < Math.Min(all.Count, (i + 1) * perColumn); j++)
                slice.Add(all[j]);
            columns.Add(slice);
        }
        return columns;
